root=Path(__file__).resolve().parents[1]/'control-panel/site'
pages={
'features':('A clear route from question to answer.','A shared support workspace with approved business knowledge and a visible human handoff.',[
('One customer conversation','Read the message, check its context, reply, add a private note and choose who handles it next.','inbox'),
('Knowledge you can review','Scan your website, check the proposed facts and approve the answers your business can stand behind.','business-brain'),
('A human when it matters','Questions outside approved knowledge enter the Human Queue, ready for an assigned teammate.','mobile-desktop'),
('Tools around your team','Routing rules, support analytics and a searchable Help Centre make the daily work easier to follow.','automations')]),
'business-brain':('Teach your business. Review every answer.','Your prices, policies, hours and FAQs belong in one place your team can check.',[
('Start with what you know','Add verified facts manually or run an authorised website scan. Scanned content starts as a proposal; it is not automatically approved.'),
('Approve before automation','Review the wording, source and confidence. Automatic answers require approved knowledge and a confidence threshold of at least 90%.'),
('Turn gaps into better answers','An unknown question creates a knowledge gap. A human can answer the customer and review a suggested FAQ for future use.'),
('Keep knowledge current','An edited fact returns to pending review. Recheck prices, opening times and policies whenever the business changes.')]),
'inbox':('The whole conversation. The next clear step.','A compact workspace for customer messages, teammate notes and human decisions.',[
('Reply with context','See customer messages alongside ticket details. Website chat replies become available in the visitor’s chat when it reconnects.'),
('Keep team notes private','Choose Internal Note for staff-only context. Mention a teammate without adding that note to the customer conversation.'),
('Give every ticket an owner','Set priority, assign a teammate, mark a conversation pending or resolve it. Reopen it when more work is needed.'),
('See what needs you','The Human Queue gathers open and pending questions the AI could not safely answer.')]),
'automations':('Let clear rules do the routing.','Make repeatable support decisions easy to understand and review.',[
('Choose the trigger','Create rules for incoming messages. Match a channel or a word in the message.'),
('Choose the action','Set priority, assign a teammate or add a tag. Order rules so the most specific cases are considered first.'),
('Review, then enable','New and edited rules start disabled. Check the conditions and run a test before enabling them.'),
('Know the release boundary','Time-based rules may appear from an existing workspace. Their scheduled execution needs an operational check before use.')]),
'analytics':('See the work. Find the gaps.','Support volume and business knowledge coverage in the same workspace.',[
('Understand demand','See conversation totals and recent daily volume, with the time period shown beside the data.'),
('Measure human and AI work','Review human replies, resolved conversations, automatic-answer containment and pending drafts.'),
('Improve the knowledge base','Use open knowledge gaps and topic coverage to choose what to teach next. Readiness is a coverage indicator, not an accuracy guarantee.'),
('Read the limits','The volume chart is capped at 1,000 recent conversations and labels the cap when reached. Other metrics use the selected reporting period.')]),
'channels':('Start with your website. Connect deliberately.','A channel should be tested from first message through to reply.',[
('Website chat','Install the small widget snippet from your workspace. Configure the allowed website origins, then test a known question and a human handoff.'),
('Email and messaging','Email, WhatsApp, Telegram and X have connection surfaces. Provider authorisation and delivery tests are required; a saved account alone does not establish readiness.'),
('Protect an existing installation','Keep one widget per page and retain the previous snippet for rollback. Start on a staging page when possible.'),
('Voice','Voice is outside the core 6.1 release. It is not offered as an active channel here.')]),
'help-centre':('Useful answers, on your customers’ terms.','Publish a simple, searchable Help Centre from reviewed articles.',[
('Write privately','A new centre begins private. Create plain-text article drafts and organise them by category.'),
('Publish intentionally','An article is public only when it is published and its centre is enabled. Editing an article returns it to draft.'),
('Make answers easy to find','Customers can search article titles and content from the public centre link. They do not need a staff account.'),
('Keep publication separate','Approving a Business Brain fact does not automatically publish a Help Centre article. Review both for their audience.')]),
'mobile-desktop':('Your support workspace, wherever you work.','One responsive web app for a phone, tablet or desktop.',[
('Install from your browser','Use the browser’s Install option on supported devices. On iPhone and iPad, use Safari’s Share → Add to Home Screen.'),
('Keep human work close','Open the Human Queue, read alerts and continue a conversation from the mobile navigation.'),
('Know when alerts arrive','Enable background alerts on each supported phone or computer. In-app notifications still refresh while DeskRoute is open.'),
('An honest offline state','The app shell can load offline, but conversations and changes require a connection. Customer data is not put into the service-worker cache.')]),
'security':('Clear boundaries for customer support.','Access control, private collaboration and reviewed knowledge are built into the workflow.',[
('Workspace access','Staff sign in to their workspace. Database checks scope protected workflows to the current user’s membership and permissions.'),
('Private by default','Internal notes are excluded from the website chat delivery path. Help Centre drafts and disabled centres stay outside public publication.'),
('Traceable actions','Reply and internal-note workflows record audit events. The interface also exposes recent workspace audit activity.'),
('Before a commercial agreement','Confirm the operator’s privacy notice, data-processing terms, retention policy and support contact during onboarding. No certification or compliance guarantee is claimed on this preview.')]),
'pricing':('A pilot scoped to your business.','DeskRoute 6.1 is in release-candidate review. Public paid checkout is not open.',[
('Agree the scope','Choose the brands, staff seats, website and initial question types with your onboarding contact.'),
('Agree the service','Confirm usage limits, support hours, data handling, fees and cancellation terms in writing before a paid rollout.'),
('Prove the workflow','Run the pilot with reviewed knowledge, a staffed Human Queue and a tested reply path.'),
('No surprise purchase','This preview does not take payment or start a subscription. Published self-service prices will follow commercial readiness.')]),
'support':('Help your team get comfortable.','Start with practical setup and daily-work guides.',[
('Getting started','Follow the documentation for access, knowledge review, widget installation and the first handoff test.','docs/'),
('A problem in the workspace','Record the page, approximate time, browser and steps to reproduce. Share a redacted screenshot with your existing onboarding contact.'),
('A customer needs help now','Use the Human Queue and your established business contact channel. In-app polling is not an emergency notification service.'),
('Support expectations','Confirm your support contact and response hours during onboarding. This preview does not advertise round-the-clock support or a response-time guarantee.')]),
'status':('Release status, without guesswork.','6.1 release candidate · updated 3 October 2026. This is a release note, not a live uptime monitor.',[
('In release review','The redesigned support workspace, PWA shell and public Help Centre are undergoing release verification.'),
('Available in the pilot','The existing website chat pilot uses approved facts, knowledge gaps and human handoff. The v6.1 panel rollout is tracked separately.'),
('Not advertised as ready','Paid self-service checkout and additional provider channel delivery remain outside verified release scope.'),
('Need operational help?','Check with your existing onboarding contact. No outage-free or all-systems-operational claim is inferred from this static page.')]),
'contact':('Start with a clear support brief.','Pilot access is arranged through your existing DeskRoute onboarding contact.',[
('Tell us about the business','Prepare your website, number of staff, typical questions, channels and preferred pilot scope.'),
('Bring the right people','Choose the person who can approve business facts and the team who will answer human handoffs.'),
('Protect customer information','Use example questions without customer personal data. Do not include passwords, private keys or payment details.'),
('Send through your agreed channel','A public sales mailbox is not yet published on this preview. Download the brief below and share it with your onboarding contact.')])}
style='''@font-face{font-family:Inter;src:url('../assets/inter-latin.woff2') format('woff2');font-weight:100 900;font-display:swap}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f7f9fb;color:#172033;font:16px/1.7 Inter,system-ui,sans-serif}a{color:inherit;text-underline-offset:4px}button,input,textarea{font:inherit}button,a{touch-action:manipulation}:focus-visible{outline:3px solid #15817a;outline-offset:5px}.skip{position:absolute;top:-100px;background:white;padding:12px}.skip:focus{top:0;z-index:20}.wrap{max-width:1180px;margin:auto;padding:0 32px}.header{background:#fff;border-bottom:1px solid #e2e7ee}.header .wrap{display:flex;align-items:center;justify-content:space-between;min-height:84px;gap:24px}.brand{display:flex;align-items:center;gap:12px;font-size:20px;font-weight:750;text-decoration:none}.logo{display:grid;place-items:center;width:40px;height:40px;background:#61dcc0;border-radius:11px;color:#0f1c2e;font-size:14px}.header nav{display:flex;align-items:center;gap:28px;font-size:14px}.header nav a{text-decoration:none}.button{display:inline-block;border:1px solid #173b5e;border-radius:8px;padding:12px 20px;text-decoration:none;background:#173b5e;color:#fff;font-weight:650;font-size:14px;cursor:pointer}.button.light{color:#172033;background:#fff;border-color:#d2dbe6}.hero{padding:88px 0 64px}.eyebrow{font-size:12px;letter-spacing:.13em;text-transform:uppercase;font-weight:750;color:#0f766e;margin:0 0 24px}h1{max-width:850px;font-size:clamp(38px,5.3vw,64px);line-height:1.1;letter-spacing:-.05em;margin:0 0 28px}h2{font-size:32px;line-height:1.25;letter-spacing:-.03em}h3{font-size:19px;line-height:1.4;margin:0 0 10px}.intro{font-size:19px;max-width:660px;color:#596579;line-height:1.65}.actions{display:flex;flex-wrap:wrap;gap:12px;margin:30px 0}.note{font-size:13px;color:#667085}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;margin:24px 0 64px}.card{border:1px solid #e2e7ee;border-radius:16px;background:white;padding:30px}.card p{color:#596579;margin-bottom:12px}.card a{font-weight:650;font-size:14px}.number{font-size:13px;color:#0f766e;margin-bottom:22px;display:block}.band{background:#0f1c2e;color:white;padding:58px 0;margin:32px 0 0}.band p{color:#bfccde;max-width:680px}.band .eyebrow{color:#61dcc0}.preview{border:1px solid #dce4ed;border-radius:18px;background:#fff;overflow:hidden;box-shadow:0 18px 60px #173b5e10;margin:20px 0 60px}.preview-bar{padding:15px 24px;border-bottom:1px solid #e2e7ee;display:flex;justify-content:space-between;font-size:13px}.preview-body{display:grid;grid-template-columns:200px 1fr;min-height:310px}.preview-side{background:#0f1c2e;color:#aab8ca;padding:28px 24px;font-size:13px}.preview-side strong{display:block;color:#61dcc0;margin-bottom:24px}.preview-main{padding:28px}.sample-bubble{background:#edf4ff;max-width:540px;padding:15px 20px;border-radius:10px;margin:18px 0;font-size:14px}.sample-bubble.customer{background:#173b5e;color:white}.pill{display:inline-block;background:#edf8f5;color:#0f766e;border-radius:99px;padding:5px 11px;font-size:12px;font-weight:650}.links{display:flex;flex-wrap:wrap;gap:12px 26px}.footer{background:white;border-top:1px solid #e2e7ee;padding:44px 0}.footer .links{font-size:13px;color:#596579;margin:28px 0}.docs-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:56px;margin:30px 0 70px}.toc{position:sticky;top:24px;align-self:start;display:grid;gap:12px;font-size:14px}.docs section{scroll-margin-top:24px;border-top:1px solid #e2e7ee;padding:24px 0}.docs h2{font-size:26px}.docs li{margin:10px 0}.docs code{font-size:13px;word-break:break-word;background:#eaf0f5;padding:2px 5px}.docs pre{white-space:pre-wrap;background:#edf1f6;padding:18px;border-radius:10px;overflow-wrap:anywhere}.notice{background:#fff7e8;border:1px solid #f1d9ac;padding:18px 24px;border-radius:10px;margin:24px 0}.menu{display:none}.menu summary{cursor:pointer;padding:10px}.menu nav{padding:16px;display:grid;gap:16px}.contact-brief{background:white;padding:28px;border:1px solid #e2e7ee;border-radius:14px;margin-bottom:64px;max-width:700px}.contact-brief label{display:block;font-weight:650;margin:16px 0 6px}.contact-brief input,.contact-brief textarea{width:100%;padding:12px;border:1px solid #ccd5e0;border-radius:8px}.contact-brief textarea{min-height:140px}.contact-brief button{margin:20px 0 0}@media(max-width:760px){.wrap{padding:0 22px}.header .wrap{min-height:76px;flex-wrap:wrap;gap:0}.header nav.desktop{display:none}.menu{display:block}.menu[open]{width:100%;order:2;padding-bottom:16px}.menu[open] summary{text-align:right}.hero{padding:52px 0 36px}.intro{font-size:17px}h1{font-size:42px}.grid{grid-template-columns:1fr;gap:16px;margin-bottom:38px}.card{padding:24px}.preview-side{display:none}.preview-body{grid-template-columns:1fr}.preview-main{padding:20px}.preview-bar{padding:12px 20px;font-size:11px}.docs-layout{grid-template-columns:1fr;gap:24px}.toc{position:static;display:flex;flex-wrap:wrap;gap:12px 20px;font-size:13px}.band{padding:40px 0}.brand{font-size:18px}.button{min-height:46px}.actions .button{flex:1;text-align:center;min-width:150px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
(root/'site.css').write_text(style,encoding='utf-8')
def document(title,description,body,depth=0):
    p='../' if depth else './'; app='../'+p
    nav=f'<a href="{p}features.html">Features</a><a href="{p}pricing.html">Pricing</a><a href="{p}docs/">Docs</a><a href="{app}signup.html">Start setup</a><a class="button" href="{app}">Sign in</a>'
    links=''.join(f'<a href="{p}{slug}.html">{e(slug.replace("-"," ").title())}</a>' for slug in pages)+f'<a href="{p}privacy.html">Privacy</a><a href="{p}terms.html">Terms</a><a href="{p}dpa.html">DPA</a><a href="{p}subprocessors.html">Subprocessors</a>'
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(description,quote=True)}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#0f1c2e"><title>{e(title)} · DeskRoute</title><link rel="icon" href="{app}assets/icon.svg"><link rel="stylesheet" href="{p}site.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap"><a class="brand" href="{p}"><span class="logo">DR</span>DeskRoute</a><nav class="desktop" aria-label="Main">{nav}</nav><details class="menu"><summary>Menu</summary><nav aria-label="Mobile">{nav}</nav></details></div></header><main id="main">{body}</main><footer class="footer"><div class="wrap"><a class="brand" href="{p}"><span class="logo">DR</span>DeskRoute</a><div class="links">{links}<a href="{p}docs/">Documentation</a></div><p class="note">Customer support, with a human touch. · 6.1 commercial preview · Sandbox billing only.</p></div></footer></body></html>'''
def cards(items):
    return '<div class="grid">'+''.join(f'<article class="card"><span class="number">{i:02d}</span><h3>{e(x[0])}</h3><p>{e(x[1])}</p>'+ (f'<a href="{x[2] if x[2].endswith("/") else x[2]+".html"}">Explore {e(x[0].lower())} →</a>' if len(x)>2 else '')+'</article>' for i,x in enumerate(items,1))+'</div>'
for slug,(title,desc,items) in pages.items():
    body=f'<div class="wrap"><section class="hero"><p class="eyebrow">{e(slug.replace("-"," "))}</p><h1>{e(title)}</h1><p class="intro">{e(desc)}</p></section>{cards(items)}'
    if slug=='contact':
        body+='''<form class="contact-brief" id="brief"><h2>Prepare an enquiry</h2><p class="note">This stays in your browser. Downloading does not submit an enquiry.</p><label for="business">Business name</label><input id="business" required maxlength="160"><label for="website">Website</label><input id="website" type="url" placeholder="https://example.com"><label for="needs">What would you like help with?</label><textarea id="needs" required maxlength="3000"></textarea><button class="button">Download brief</button><p id="briefStatus" role="status" class="note"></p></form><script src="./contact.js" defer></script>'''
    body+='</div>'
    (root/(slug+'.html')).write_text(document(title,desc,body),encoding='utf-8')
(root/'contact.js').write_text('''document.querySelector('#brief').addEventListener('submit',event=>{event.preventDefault();const text='DeskRoute pilot enquiry\\nBusiness: '+document.querySelector('#business').value+'\\nWebsite: '+document.querySelector('#website').value+'\\n\\n'+document.querySelector('#needs').value;const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='deskroute-pilot-enquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#briefStatus').textContent='Brief downloaded. Share it with your existing onboarding contact. Nothing has been submitted.';});''',encoding='utf-8')
home='''<div class="wrap"><section class="hero"><p class="eyebrow">Approved knowledge. A human when it matters.</p><h1>Clear answers.<br>A calmer inbox.</h1><p class="intro">Give everyday questions a reliable starting point. Give your team the context to handle everything else.</p><div class="actions"><a class="button" href="business-brain.html">See how it works →</a><a class="button light" href="../">Open your workspace</a></div><p class="note">DeskRoute 6.1 preview · Website chat and human support, together.</p></section><div class="preview" aria-label="Illustrative support workflow"><div class="preview-bar"><strong>Support workspace</strong><span>Illustration · example conversation</span></div><div class="preview-body"><aside class="preview-side"><strong>DR · DeskRoute</strong><p>Inbox</p><p>Human Queue</p><p>Business Brain</p><p>Analytics</p></aside><div class="preview-main"><span class="pill">Approved business knowledge</span><div class="sample-bubble customer">Can I change my booking?</div><div class="sample-bubble">Your team’s reviewed policy provides the starting point. An unusual request goes to a person.</div><p class="note">Learn → Review → Answer → Improve</p></div></div></div><p class="eyebrow">Built around the work</p><h2>Knowledge, conversations and people.<br>One connected workflow.</h2>'''+cards(pages['features'][2])+'''</div><section class="band"><div class="wrap"><p class="eyebrow">You stay in control</p><h2>Start small. Teach well. Keep a human close.</h2><p>Review your business facts, test the widget on your website and give the Human Queue a clear owner. Expand only when the answers and the handoff work for your business.</p><a class="button light" href="docs/">Read the getting-started guide</a></div></section>'''
(root/'index.html').write_text(document('Clear answers. A calmer inbox.','Customer support with approved business knowledge and a clear human handoff.',home),encoding='utf-8')
sections=[
('access','Sign in and workspace access','''<p>Open your DeskRoute workspace link and sign in with the account supplied during onboarding. Choose the correct business in the workspace selector. On mobile, the same selector is in Settings.</p><p>If you cannot sign in, check the email address and contact your workspace owner through your established channel. Choose Set or reset your password on the sign-in page to request a recovery email for an existing account. Open the newest email link and choose your own password; use that same account on desktop and phone. New workspace access must be arranged by an owner. Never share your password with support.</p><p>Owners and admins manage workspace settings. Agents reply and add notes. Viewers read. Custom roles use their configured permissions.</p>'''),
('getting-started','Your first successful handoff','''<ol><li>Confirm who owns the workspace and who will watch the Human Queue.</li><li>Add a small set of verified business facts: services, hours, contact, pricing and policies.</li><li>Review each fact in Business Brain. Keep uncertain information pending.</li><li>Install the website widget on a staging page and configure its allowed origin.</li><li>Ask a question covered by approved knowledge. Confirm the reply.</li><li>Ask a question outside that knowledge. Confirm the gap, assignment and staff alert.</li><li>Add an internal note and confirm it never appears in the visitor chat.</li><li>Send a public reply, reconnect the visitor chat and confirm it appears once.</li></ol><p>Keep automatic mode off until these checks pass for your business.</p>'''),
('brain','Build and maintain the Business Brain','''<p>Choose Business Brain → Add fact, or Scan website. Scan only a website you are authorised to manage. A scan proposes facts for review; it does not install the widget or approve its own answers.</p><p>Expand a fact to inspect the answer and source. Approve only information you have checked. Editing an approved fact returns it to pending. Do not put customer personal data or secrets in general business knowledge.</p><p>Knowledge Gaps show questions that could not be answered safely. Teach an answer, review it, and approve it. Learned FAQ suggestions also require approval.</p><p>Settings provides Suggest only, Review before sending and Automatic approved answers. Automatic answers require approved facts and at least 90% confidence. Confidence and readiness scores are indicators, not guarantees.</p>'''),
('inbox','Reply, collaborate and resolve','''<p>Open Inbox or Human Queue and select a conversation. The header provides status, priority and assignee. A public website reply becomes available to the visitor’s chat on its next successful sync; “saved” is not proof that the visitor has read it.</p><p>Choose Internal Note for private team discussion. You can mention another member of the same workspace. Notes never belong in the public reply box.</p><p>Mark pending when you are waiting on something. Resolve when the conversation is complete. Reopen when work resumes. Changing status does not send a reply.</p><p>Text drafts remain in memory while switching conversations. They are cleared on sign-out or workspace change and are not an offline outbox.</p><p>The inbox shows the most recent 200 conversations and up to 200 recent messages per open thread. Search applies to the loaded conversations.</p>'''),
('channels','Install website chat and check channels','''<p>Open Channels → Website Chat → Installation &amp; widgets. Copy the snippet for the correct brand. Install it once before the closing body tag or in your website’s approved script area.</p><pre>&lt;script src="https://deskroute-ai-v6-preview.onrender.com/deskroute-widget.js"
  data-deskroute-key="YOUR_WIDGET_PUBLIC_KEY" defer&gt;&lt;/script&gt;</pre><p>The public widget key is an installation identifier, not a staff credential. Never put a secret or service-role key in a website. Use the exact allowed origins shown for the widget, including the correct www/non-www hostname.</p><p>Email, WhatsApp, Telegram and X require provider authorisation and separate inbound/outbound delivery checks. The 6.1 reply composer only sends website chat replies. Add an internal note or use your established provider workflow for other channels.</p>'''),
('automations','Review routing rules','''<p>Open Automations and create a rule for an incoming message. Select a channel or message keyword, then a priority, assignee or tag. Set the order and choose whether matching stops further rules.</p><p>Saving creates or updates a disabled rule. Review the conditions and test the outcome before enabling it. Time-based rules require a separately verified scheduler; do not assume they run because they appear in the list.</p>'''),
('help','Publish a Help Centre','''<p>Create a help centre for your brand. It starts private. Add an article with a title, URL slug, category and plain-text body. Review the draft, publish the article and then enable the centre.</p><p>Use Open public centre to check what an anonymous visitor sees. Only published articles in an enabled centre are returned. Unpublish an article or make the centre private to remove access. Saving an article edit returns it to draft.</p><p>Help articles and approved AI facts are separate publication decisions. Keep both up to date.</p>'''),
('notifications','Alerts, mobile and desktop','''<p>Install the app from a supported browser’s menu. On iPhone or iPad, use Safari → Share → Add to Home Screen. On Android and desktop, use Install app when offered. This is a web app; a separate app-store package is not included.</p><p>Notifications include assignments and internal mentions. In Settings, select the types of alerts you want. Open an alert to visit the conversation or mark it read.</p><p>Enable background alerts in Settings on each supported phone or computer that should be notified. In-app alerts continue to refresh while DeskRoute is visible and online. Device last-seen activity does not prove that a teammate is available.</p>'''),
('analytics','Understand the numbers','''<p>Analytics shows the selected brand’s last 30 days and a seven-day volume chart. It includes conversations, human replies, resolved work, pending drafts and knowledge gaps. Check the period and the chart’s 1,000-conversation limit before comparing figures.</p><p>Knowledge readiness measures topic coverage and unresolved gaps. A high score does not replace checking the business’s current facts.</p>'''),
('troubleshooting','Troubleshoot safely','''<ul><li><strong>Page failed to load:</strong> check your connection, retry, and sign in again if the session ended.</li><li><strong>A save was rejected:</strong> confirm the correct workspace and your role, then refresh. A permission error is not a successful save.</li><li><strong>Widget missing:</strong> check the snippet is installed once, the key matches, the widget is enabled and the origin is allowed.</li><li><strong>Reply not visible:</strong> confirm it was a Public Reply on Website Chat, reconnect the visitor chat and check the same conversation.</li><li><strong>No alerts:</strong> check notification permission, Settings → background alerts, the connection and notification preferences. Send a test alert from Settings.</li><li><strong>Offline:</strong> the shell may load, but data and saves need a connection. Do not assume unsent text has been queued.</li></ul><p>Send your onboarding contact the page, time, browser and steps, with a redacted screenshot. Do not send tokens or passwords.</p>'''),
('release','6.1 release boundaries','''<p>This is a release candidate. Website chat is the supported reply path. Background Web Push is available after device opt-in. Paid self-service checkout, additional provider delivery and scheduled automations are not advertised as verified.</p><p>Commercial onboarding must confirm the support contact, support hours, plan limits, fees, privacy/data-processing terms and retention policy. The preview takes no payment.</p>''')]
body='<div class="wrap"><section class="hero"><p class="eyebrow">Documentation · v6.1</p><h1>From first fact to<br>resolved conversation.</h1><p class="intro">Practical guides for setting up DeskRoute and running the daily support work.</p></section><div class="docs-layout"><nav class="toc" aria-label="Guide chapters">'+''.join(f'<a href="#{x[0]}">{e(x[1])}</a>' for x in sections)+'</nav><article class="docs">'+''.join(f'<section id="{slug}"><h2>{e(title)}</h2>{content}</section>' for slug,title,content in sections)+'</article></div></div>'
(root/'docs/index.html').write_text(document('Documentation','Set up and run DeskRoute: knowledge, inbox, website chat, human handoff and mobile alerts.',body,1),encoding='utf-8')
print('Built',len(pages)+2,'website and documentation pages')
# --- Commercial preview overrides (sandbox-first) ---
commercial_css = r'''
.hero-commercial{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(300px,.9fr);gap:54px;align-items:center;padding:88px 0 62px}
.hero-commercial h1{font-size:clamp(42px,5.7vw,72px)}
.hero-panel{background:#0f1c2e;color:#fff;border-radius:24px;padding:30px;box-shadow:0 24px 70px #0f1c2e20}
.hero-panel p{color:#bfccde}.hero-panel .pill{margin-bottom:14px}.hero-panel ol{padding-left:20px;color:#dce7f4}
.step-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:26px 0 68px}
.step{background:#fff;border:1px solid #e2e7ee;border-radius:16px;padding:24px}.step strong{display:block;margin-bottom:8px}.step p{font-size:14px;color:#596579}
.plan-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin:26px 0 44px}
.plan-card{background:#fff;border:1px solid #dce4ed;border-radius:18px;padding:28px;display:flex;flex-direction:column;gap:18px}
.plan-card.featured{border:2px solid #15817a;box-shadow:0 18px 55px #0f766e15}
.price{font-size:38px;letter-spacing:-.04em;font-weight:800;line-height:1}.price small{font-size:14px;font-weight:550;color:#667085;letter-spacing:0}
.plan-list{list-style:none;padding:0;margin:0;display:grid;gap:8px;color:#596579;font-size:14px}.plan-list li:before{content:"✓";color:#0f766e;font-weight:800;margin-right:8px}
.code-card{background:#081421;color:#eaf5ff;border-radius:16px;padding:24px;overflow:auto;margin:24px 0 62px}.code-card code{font:13px/1.7 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre}
.section-head{max-width:760px;margin-top:68px}.section-head p{color:#596579}
.trust-row{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}.trust-row span{background:#edf8f5;color:#0f766e;border-radius:999px;padding:6px 12px;font-size:12px;font-weight:700}
.sandbox-flag{display:inline-block;background:#fff3da;color:#7a4a00;border:1px solid #f0d29b;border-radius:999px;padding:6px 11px;font-size:12px;font-weight:750}
@media(max-width:900px){.hero-commercial{grid-template-columns:1fr;gap:28px}.step-grid{grid-template-columns:repeat(2,1fr)}.plan-grid{grid-template-columns:1fr}}
@media(max-width:520px){.step-grid{grid-template-columns:1fr}.hero-commercial{padding:52px 0 34px}.plan-card{padding:23px}}
'''
with (root/'site.css').open('a',encoding='utf-8') as f:
    f.write(commercial_css)

commercial_home = '''<div class="wrap"><section class="hero-commercial"><div><p class="eyebrow">Customer support, with a human touch</p><h1>Customer support that knows when to hand over.</h1><p class="intro">DeskRoute learns the business knowledge you approve, answers routine website questions and brings your team in when a person is needed.</p><div class="actions"><a class="button" href="../signup.html">Start your setup →</a><a class="button light" href="pricing.html">See pricing</a></div><div class="trust-row"><span>Approved knowledge</span><span>Human handoff</span><span>Website chat</span><span>Phone & desktop alerts</span></div><p class="note">6.1 commercial preview · Sandbox billing only · No live card charges from this site.</p></div><aside class="hero-panel"><span class="pill">A safer AI support loop</span><h2>Teach it once. Keep control.</h2><ol><li>Scan your authorised website.</li><li>Review the facts DeskRoute proposes.</li><li>Install one website script.</li><li>AI answers what it can prove.</li><li>Everything else reaches your Human Queue.</li></ol></aside></section><section class="section-head"><p class="eyebrow">From website to human</p><h2>Go live without building a support department from scratch.</h2><p>DeskRoute gives smaller teams the workflow normally spread across a chatbot, shared inbox, knowledge base and alerting system.</p></section><div class="step-grid"><article class="step"><span class="number">01</span><strong>Connect your business</strong><p>Create a workspace, add your website and set your hours.</p></article><article class="step"><span class="number">02</span><strong>Build the Business Brain</strong><p>Scan your site and approve prices, services, policies and FAQs.</p></article><article class="step"><span class="number">03</span><strong>Install in one line</strong><p>Add the hosted DeskRoute widget to your website.</p></article><article class="step"><span class="number">04</span><strong>Let humans handle the edge cases</strong><p>Unknown or sensitive questions are handed to your team with context.</p></article></div><section class="section-head"><p class="eyebrow">Business Brain</p><h2>AI answers from what your business has actually approved.</h2><p>Website scans create proposals, not truth. Your team reviews knowledge before it can become a trusted answer. When a new question exposes a gap, the Human Queue handles the customer while you decide whether to teach the answer for next time.</p></section><div class="preview"><div class="preview-bar"><strong>Business Brain → Website chat → Human Queue</strong><span>Illustrative workflow</span></div><div class="preview-body"><aside class="preview-side"><strong>DeskRoute</strong><p>Inbox</p><p>Human Queue</p><p>Business Brain</p><p>Analytics</p></aside><div class="preview-main"><span class="pill">Approved fact found</span><div class="sample-bubble customer">What time are you open?</div><div class="sample-bubble">DeskRoute can answer from your reviewed opening hours. If the answer is missing, conflicting or sensitive, it asks a person instead.</div><p class="note">No silent self-training from every customer message.</p></div></div></div><section class="section-head"><p class="eyebrow">Install</p><h2>One hosted script on the customer website.</h2><p>Each business gets its own public widget key. Private API and database credentials never belong in the customer's page.</p></section><div class="code-card"><code>&lt;script
  src="https://deskroute-ai-v6-preview.onrender.com/deskroute-widget.js"
  data-deskroute-key="YOUR_DESKROUTE_WIDGET_KEY"
  defer&gt;&lt;/script&gt;</code></div></div><section class="band"><div class="wrap"><p class="eyebrow">Keep the human close</p><h2>Routine answers move faster. Important conversations still reach a person.</h2><p>DeskRoute is designed to hand over when approved knowledge is missing, confidence is too low or a sensitive topic needs human judgement.</p><a class="button light" href="features.html">Explore the product →</a></div></section>'''
(root/'index.html').write_text(document('Customer support that knows when to hand over','DeskRoute combines approved business knowledge, AI website support and a clear human handoff.',commercial_home),encoding='utf-8')

pricing_body = '''<div class="wrap"><section class="hero"><p class="eyebrow">Pricing preview</p><h1>Simple plans for support teams that want AI without losing control.</h1><p class="intro">These are proposed launch prices running in Stripe sandbox while we finish commercial sign-off. Test checkout takes no real money.</p><div class="trust-row"><span>14-day workspace trial</span><span>Monthly plans</span><span>Cancel through billing controls when live</span><span>Managed Payments sandbox</span></div></section><span class="sandbox-flag">SANDBOX · TEST PAYMENTS ONLY</span><div class="plan-grid"><article class="plan-card"><div><p class="eyebrow">Starter</p><h2 class="price">£19 <small>/ month</small></h2><p>For a small business starting with one website and a compact support team.</p></div><ul class="plan-list"><li>3 staff seats</li><li>1 brand</li><li>500 conversations / month</li><li>2,000 AI calls / month</li><li>Website chat + Business Brain</li><li>Human Queue + analytics</li></ul><a class="button light" href="../signup.html?plan=starter">Start Starter</a></article><article class="plan-card featured"><div><p class="eyebrow">Growth</p><h2 class="price">£49 <small>/ month</small></h2><p>For a growing support operation with more people, brands and automation.</p></div><ul class="plan-list"><li>10 staff seats</li><li>3 brands</li><li>2,500 conversations / month</li><li>10,000 AI calls / month</li><li>Email foundation + CMS integrations</li><li>Automations + analytics</li></ul><a class="button" href="../signup.html?plan=growth">Start Growth</a></article><article class="plan-card"><div><p class="eyebrow">Pro</p><h2 class="price">£99 <small>/ month</small></h2><p>For multi-brand teams that need higher limits and stronger operational controls.</p></div><ul class="plan-list"><li>25 staff seats</li><li>10 brands</li><li>10,000 conversations / month</li><li>30,000 AI calls / month</li><li>Advanced controls</li><li>Priority support target for launch</li></ul><a class="button light" href="../signup.html?plan=pro">Start Pro</a></article></div><div class="notice"><strong>Commercial preview</strong><p>The prices and limits above are currently configured in Stripe test mode and DeskRoute's sandbox plan catalog. They are not live charges yet. Live activation waits for final price approval, live Stripe account activation and legal/commercial sign-off.</p></div><section class="section-head"><p class="eyebrow">Included in every plan</p><h2>The safety and human-control model is not an upsell.</h2></section><div class="grid"><article class="card"><h3>Controlled learning</h3><p>Website scans and support gaps create reviewable knowledge proposals. They are not silently auto-approved.</p></article><article class="card"><h3>Grounded answers</h3><p>Automatic replies require approved facts and strong grounding. Unknown questions go to your team.</p></article><article class="card"><h3>Sensitive-topic handoff</h3><p>High-impact topics can force a human response rather than improvising advice.</p></article><article class="card"><h3>Install anywhere</h3><p>Use the hosted website widget and install the staff workspace as a PWA on supported phones and computers.</p></article></div></div>'''
(root/'pricing.html').write_text(document('Pricing preview','DeskRoute Starter, Growth and Pro commercial pricing preview in Stripe sandbox.',pricing_body),encoding='utf-8')

trust_pages = {
'privacy':('Privacy overview','How DeskRoute is designed to handle customer-support data during the commercial preview.','''<p>This page is a product/privacy overview for the commercial preview, not a substitute for the final operator privacy notice.</p><h2>What DeskRoute processes</h2><p>DeskRoute can process support conversations, contact details supplied by visitors, business knowledge, staff account data, notification/device records and operational audit events.</p><h2>Why</h2><p>The data is used to deliver the support workspace, website chat, approved-knowledge answers, human handoff and operational security.</p><h2>Commercial sign-off</h2><p>Before live paid onboarding, the operator must publish the final privacy notice, retention periods, controller/processor roles and rights-request contact.</p>'''),
'terms':('Terms status','Commercial terms are being prepared for live paid DeskRoute subscriptions.','''<p>Live self-service subscriptions are not enabled from this preview. Final terms must state plan limits, fees, cancellation, acceptable use, support scope and service responsibilities before live checkout is opened.</p><p>The Stripe sandbox checkout is for technical testing only and does not create a live paid service agreement.</p>'''),
'dpa':('Data Processing Agreement status','DeskRoute data-processing terms are in commercial review.','''<p>A final DPA is required before broad commercial onboarding where DeskRoute processes personal data on a customer's behalf.</p><p>The final document should cover processing instructions, confidentiality, security measures, subprocessors, assistance with rights requests, incident handling, deletion/return and international transfers where applicable.</p>'''),
'subprocessors':('Subprocessor overview','Infrastructure used by the DeskRoute commercial preview.','''<p>The commercial preview currently relies on third-party infrastructure for hosting, database/authentication, AI processing, payments and transactional delivery. The final public subprocessor list must name the contracted providers, purpose, processing location where required and change-notification process.</p><p>Do not treat this preview page as the final contractual subprocessor schedule.</p>''')
}
