    body=f'<div class="wrap"><section class="hero"><p class="eyebrow">Commercial preview</p><h1>{e(title)}</h1><p class="intro">{e(desc)}</p></section><article class="docs"><section>{content}</section></article></div>'
    (root/(slug+'.html')).write_text(document(title,desc,body),encoding='utf-8')

